package com.searchableloottracker;

import static org.junit.Assert.assertEquals;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Random;
import org.junit.Test;

public class LootHistoryRetentionTest
{
	private static final Instant NOW = Instant.parse("2026-08-22T12:00:00Z");

	@Test
	public void excludesHistoryOlderThanLootTrackersMaximumAge()
	{
		Entry cutoff = new Entry("cutoff", NOW.minus(365, ChronoUnit.DAYS), 1);
		Entry expired = new Entry("expired", NOW.minus(365, ChronoUnit.DAYS).minusSeconds(1), 1);

		List<Entry> retained = select(Arrays.asList(expired, cutoff));

		assertEquals(1, retained.size());
		assertEquals("cutoff", retained.get(0).name);
	}

	@Test
	public void removesTheOldestEntryWhenTheDropLimitIsReached()
	{
		Entry oldest = new Entry("oldest", NOW.minusSeconds(2), 500);
		Entry newest = new Entry("newest", NOW, 600);

		List<Entry> retained = select(Arrays.asList(oldest, newest));

		assertEquals(1, retained.size());
		assertEquals("newest", retained.get(0).name);
	}

	@Test
	public void treatsTheDropLimitAsExclusiveLikeLootTracker()
	{
		Entry older = new Entry("older", NOW.minusSeconds(1), LootHistoryRetention.MAX_DROPS - 1);
		Entry reachesLimit = new Entry("reaches-limit", NOW, 1);

		List<Entry> retained = select(Arrays.asList(older, reachesLimit));

		assertEquals(1, retained.size());
		assertEquals("reaches-limit", retained.get(0).name);
	}

	@Test
	public void matchesLootTrackersTieOrderingAtTheDropLimit()
	{
		Entry first = new Entry("first", NOW, 500);
		Entry second = new Entry("second", NOW, 600);

		List<Entry> retained = select(Arrays.asList(first, second));

		assertEquals(1, retained.size());
		assertEquals("first", retained.get(0).name);
	}

	@Test
	public void customZeroLimitsLoadAllHistory()
	{
		Entry ancient = new Entry("ancient", NOW.minus(1000, ChronoUnit.DAYS), 2000);
		Entry recent = new Entry("recent", NOW, 2000);

		List<Entry> retained = selectCustom(Arrays.asList(ancient, recent), 0, 0);

		assertEquals(2, retained.size());
		assertEquals("ancient", retained.get(0).name);
		assertEquals("recent", retained.get(1).name);
	}

	@Test
	public void customAgeExcludesOnlyEntriesOutsideItsCutoff()
	{
		Entry cutoff = new Entry("cutoff", NOW.minus(730, ChronoUnit.DAYS), 1);
		Entry expired = new Entry("expired", NOW.minus(730, ChronoUnit.DAYS).minusSeconds(1), 1);

		List<Entry> retained = selectCustom(Arrays.asList(expired, cutoff), 730, 0);

		assertEquals(1, retained.size());
		assertEquals("cutoff", retained.get(0).name);
	}

	@Test
	public void customDropLimitIsInclusive()
	{
		Entry older = new Entry("older", NOW.minusSeconds(1), 600);
		Entry newer = new Entry("newer", NOW, 400);

		List<Entry> retained = selectCustom(Arrays.asList(older, newer), 0, 1000);

		assertEquals(2, retained.size());
	}

	@Test
	public void customDropLimitKeepsTheMostRecentEntriesThatFit()
	{
		Entry oldest = new Entry("oldest", NOW.minusSeconds(2), 600);
		Entry newest = new Entry("newest", NOW, 500);

		List<Entry> retained = selectCustom(Arrays.asList(oldest, newest), 0, 1000);

		assertEquals(1, retained.size());
		assertEquals("newest", retained.get(0).name);
	}

	@Test
	public void optimizedRetentionHandlesOutOfOrderEntries()
	{
		Entry newest = new Entry("newest", NOW, 900);
		Entry oldest = new Entry("oldest", NOW.minusSeconds(2), 100);
		Entry middle = new Entry("middle", NOW.minusSeconds(1), 200);

		List<Entry> retained = select(Arrays.asList(newest, oldest, middle));

		assertEquals(2, retained.size());
		assertEquals("middle", retained.get(0).name);
		assertEquals("newest", retained.get(1).name);
	}

	@Test
	public void unlimitedHistoryIsReturnedOldestFirst()
	{
		Entry newest = new Entry("newest", NOW, 1);
		Entry oldest = new Entry("oldest", NOW.minusSeconds(2), 1);
		Entry middle = new Entry("middle", NOW.minusSeconds(1), 1);

		List<Entry> retained = selectCustom(Arrays.asList(newest, oldest, middle), 0, 0);

		assertEquals(Arrays.asList("oldest", "middle", "newest"), Arrays.asList(
			retained.get(0).name, retained.get(1).name, retained.get(2).name));
	}

	@Test
	public void optimizedStandardRetentionMatchesPreviousSelection()
	{
		Random random = new Random(42);
		for (int iteration = 0; iteration < 100; iteration++)
		{
			List<Entry> entries = new ArrayList<>();
			for (int index = 0; index < 100; index++)
			{
				entries.add(new Entry("entry-" + index, NOW.minusSeconds(index + 1), random.nextInt(200)));
			}
			Collections.shuffle(entries, random);

			assertEquals(previousStandardSelection(entries), select(entries));
		}
	}

	@Test
	public void optimizedCustomRetentionMatchesPreviousSelection()
	{
		Random random = new Random(84);
		for (int iteration = 0; iteration < 100; iteration++)
		{
			List<Entry> entries = new ArrayList<>();
			for (int index = 0; index < 100; index++)
			{
				entries.add(new Entry("entry-" + index, NOW.minusSeconds(index + 1), random.nextInt(200)));
			}
			Collections.shuffle(entries, random);

			assertEquals(previousCustomSelection(entries, 1000), selectCustom(entries, 0, 1000));
		}
	}

	private static List<Entry> previousStandardSelection(List<Entry> entries)
	{
		List<Entry> retained = new ArrayList<>();
		Comparator<Entry> oldestFirst = Comparator.comparing(entry -> entry.lastReceived);
		int retainedDrops = 0;
		for (Entry entry : entries)
		{
			if (retainedDrops >= LootHistoryRetention.MAX_DROPS && !retained.isEmpty()
				&& retained.get(0).lastReceived.isAfter(entry.lastReceived))
			{
				continue;
			}
			int index = Collections.binarySearch(retained, entry, oldestFirst);
			retained.add(index < 0 ? -index - 1 : index, entry);
			retainedDrops += entry.drops;
			if (retainedDrops >= LootHistoryRetention.MAX_DROPS)
			{
				retainedDrops -= retained.remove(0).drops;
			}
		}
		return retained;
	}

	private static List<Entry> previousCustomSelection(List<Entry> entries, int maximumDrops)
	{
		List<Entry> retained = new ArrayList<>();
		Comparator<Entry> oldestFirst = Comparator.comparing(entry -> entry.lastReceived);
		long retainedDrops = 0;
		for (Entry entry : entries)
		{
			if (retainedDrops >= maximumDrops && !retained.isEmpty()
				&& retained.get(0).lastReceived.isAfter(entry.lastReceived))
			{
				continue;
			}
			int index = Collections.binarySearch(retained, entry, oldestFirst);
			retained.add(index < 0 ? -index - 1 : index, entry);
			retainedDrops += entry.drops;
			while (retainedDrops > maximumDrops && !retained.isEmpty())
			{
				retainedDrops -= retained.remove(0).drops;
			}
		}
		return retained;
	}

	private static List<Entry> select(List<Entry> entries)
	{
		return LootHistoryRetention.select(entries, NOW, entry -> entry.lastReceived, entry -> entry.drops);
	}

	private static List<Entry> selectCustom(List<Entry> entries, int maximumAgeDays, int maximumDrops)
	{
		return LootHistoryRetention.selectCustom(entries, NOW, maximumAgeDays, maximumDrops,
			entry -> entry.lastReceived, entry -> entry.drops);
	}

	private static final class Entry
	{
		private final String name;
		private final Instant lastReceived;
		private final int drops;

		private Entry(String name, Instant lastReceived, int drops)
		{
			this.name = name;
			this.lastReceived = lastReceived;
			this.drops = drops;
		}
	}
}

package com.searchableloottracker.search;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.searchableloottracker.model.LootItem;
import com.searchableloottracker.model.LootSource;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import org.junit.Test;
import net.runelite.client.plugins.loottracker.LootTrackerPriceType;

public class LootSearchTest
{
	@Test
	public void gePricesAboveIntegerLimitPreserveTotalsAndOrdering()
	{
		LootItem expensive = new LootItem(1, "Expensive item", 2, 3_000_000_000L, 100);
		LootItem ordinary = new LootItem(2, "Ordinary item", 1, 1_000, 200);
		LootSource source = new LootSource("Boss", "NPC", 1, Arrays.asList(ordinary, expensive));
		LootSearchResult result = LootSearch.search(Collections.singletonList(source), "", SearchMode.SOURCE).get(0);

		assertEquals(3_000_000_000L, expensive.getGePrice());
		assertEquals(6_000_000_000L, expensive.getTotalGeValue());
		assertSame(expensive, result.getVisibleItems().get(0));
		assertEquals(6_000_001_000L, source.getTotalValue(LootTrackerPriceType.GRAND_EXCHANGE));
		assertEquals(6_000_001_000L, result.getTotalValue(LootTrackerPriceType.GRAND_EXCHANGE));
		assertEquals(400L, result.getTotalValue(LootTrackerPriceType.HIGH_ALCHEMY));
	}

	@Test
	public void allSourceFilterUsesConciseLabel()
	{
		assertEquals("All", SourceTypeFilter.ALL.toString());
	}

	private final List<LootSource> sources = Arrays.asList(
		new LootSource("Vorkath", "NPC", 10, Arrays.asList(
			new LootItem(11230, "Dragon dart tip", 120, 1_000, 300),
			new LootItem(995, "Coins", 50_000, 1, 1))),
		new LootSource("Zulrah", "NPC", 4, Collections.singletonList(
			new LootItem(12934, "Zulrah's scales", 500, 100, 60)))
	);

	@Test
	public void sourceSearchReturnsAllDropsForMatchingSource()
	{
		List<LootSearchResult> results = LootSearch.search(sources, "vork", SearchMode.SOURCE);

		assertEquals(1, results.size());
		assertEquals("Vorkath", results.get(0).getSource().getName());
		assertEquals(2, results.get(0).getVisibleItems().size());
		assertSame(sources.get(0).getItems(), results.get(0).getVisibleItems());
	}

	@Test
	public void normalizedIgnoredLootCanBeReusedAcrossSearches()
	{
		java.util.Set<String> ignoredItems = LootSearchCriteria.normalizeNames(
			Collections.singletonList(" Coins "));
		LootSearchCriteria criteria = LootSearchCriteria.withNormalizedIgnoredLoot("vorkath",
			SearchMode.SOURCE, LootSortOrder.MOST_RECENT, SourceTypeFilter.ALL,
			LootTrackerPriceType.GRAND_EXCHANGE, false, ignoredItems, Collections.emptySet());

		LootSearchResult result = LootSearch.search(sources, criteria).get(0);

		assertEquals(1, result.getVisibleItems().size());
		assertEquals("Dragon dart tip", result.getVisibleItems().get(0).getName());
	}

	@Test
	public void dropSearchReturnsOnlyMatchingDropsAcrossSources()
	{
		List<LootSearchResult> results = LootSearch.search(sources, "dragon dart", SearchMode.DROP);

		assertEquals(1, results.size());
		assertEquals(1, results.get(0).getVisibleItems().size());
		assertEquals("Dragon dart tip", results.get(0).getVisibleItems().get(0).getName());
	}

	@Test
	public void emptySearchReturnsEverySource()
	{
		assertEquals(2, LootSearch.search(sources, " ", SearchMode.DROP).size());
	}

	@Test
	public void itemsAreOrderedByTrackedGeValueLikeLootTracker()
	{
		LootSearchResult vorkath = LootSearch.search(sources, "vorkath", SearchMode.SOURCE).get(0);

		assertEquals("Dragon dart tip", vorkath.getVisibleItems().get(0).getName());
		assertEquals("Coins", vorkath.getVisibleItems().get(1).getName());
	}

	@Test
	public void sourcesAreOrderedByMostRecentLoot()
	{
		LootSource older = new LootSource("Abyssal demon", "NPC", 1,
			Instant.parse("2026-01-01T00:00:00Z"), Collections.singletonList(
				new LootItem(995, "Coins", 1, 1, 1)));
		LootSource newer = new LootSource("Zulrah", "NPC", 1,
			Instant.parse("2026-02-01T00:00:00Z"), Collections.singletonList(
				new LootItem(995, "Coins", 1, 1, 1)));

		List<LootSearchResult> results = LootSearch.search(Arrays.asList(older, newer), "", SearchMode.SOURCE);

		assertEquals("Zulrah", results.get(0).getSource().getName());
		assertEquals("Abyssal demon", results.get(1).getSource().getName());
	}

	@Test
	public void dropSearchAggregatesQuantitiesAndGeValueAcrossSources()
	{
		LootSource first = new LootSource("Guard", "NPC", 20, Collections.singletonList(
			new LootItem(1215, "Dragon dagger", 2, 18_000, 12_000)));
		LootSource second = new LootSource("Ninja impling", "EVENT", 10, Collections.singletonList(
			new LootItem(1215, "Dragon dagger", 5, 18_000, 12_000)));

		List<LootSearchResult> results = LootSearch.search(Arrays.asList(first, second), "dragon dagger", SearchMode.DROP);

		assertEquals(2, results.size());
		assertEquals(2, results.get(0).getTotalQuantity());
		assertEquals(5, results.get(1).getTotalQuantity());
		assertEquals(7, LootSearch.totalQuantity(results));
		assertEquals(30, LootSearch.totalSourceCount(results));
		assertEquals(126_000, LootSearch.totalValue(results, LootTrackerPriceType.GRAND_EXCHANGE));
	}

	@Test
	public void sourceIsTheDefaultMode()
	{
		assertEquals(SearchMode.SOURCE, SearchMode.values()[0]);
	}

	@Test
	public void supportsLeastRecentAndAlphabeticalSorting()
	{
		LootSource alphabeticalFirst = new LootSource("Abyssal demon", "NPC", 1,
			Instant.parse("2026-02-01T00:00:00Z"), Collections.singletonList(
				new LootItem(995, "Coins", 1, 1, 1)));
		LootSource oldest = new LootSource("Zulrah", "NPC", 1,
			Instant.parse("2026-01-01T00:00:00Z"), Collections.singletonList(
				new LootItem(995, "Coins", 1, 1, 1)));

		List<LootSearchResult> leastRecent = LootSearch.search(Arrays.asList(alphabeticalFirst, oldest),
			criteria("", SearchMode.SOURCE, LootSortOrder.LEAST_RECENT, SourceTypeFilter.ALL,
				LootTrackerPriceType.GRAND_EXCHANGE, true, Collections.emptySet(), Collections.emptySet()));
		List<LootSearchResult> alphabetical = LootSearch.search(Arrays.asList(oldest, alphabeticalFirst),
			criteria("", SearchMode.SOURCE, LootSortOrder.ALPHABETICAL, SourceTypeFilter.ALL,
				LootTrackerPriceType.GRAND_EXCHANGE, true, Collections.emptySet(), Collections.emptySet()));

		assertEquals("Zulrah", leastRecent.get(0).getSource().getName());
		assertEquals("Abyssal demon", alphabetical.get(0).getSource().getName());
	}

	@Test
	public void sourceTypeFiltersUseRecordTypesAndKeepUnknownTypesInOther()
	{
		LootSource event = new LootSource("Barrows", "EVENT", 1, Collections.singletonList(
			new LootItem(995, "Coins", 1, 1, 1)));
		LootSource futureType = new LootSource("Future source", "FUTURE_TYPE", 1, Collections.singletonList(
			new LootItem(995, "Coins", 1, 1, 1)));
		List<LootSource> all = Arrays.asList(sources.get(0), event, futureType);

		assertEquals(1, LootSearch.search(all, criteria("", SearchMode.SOURCE, LootSortOrder.MOST_RECENT,
			SourceTypeFilter.EVENT, LootTrackerPriceType.GRAND_EXCHANGE, true,
			Collections.emptySet(), Collections.emptySet())).size());
		assertEquals("Future source", LootSearch.search(all, criteria("", SearchMode.SOURCE,
			LootSortOrder.MOST_RECENT, SourceTypeFilter.OTHER, LootTrackerPriceType.GRAND_EXCHANGE,
			true, Collections.emptySet(), Collections.emptySet())).get(0).getSource().getName());
	}

	@Test
	public void ignoredLootMirrorsVisibilitySetting()
	{
		HashSet<String> ignoredItems = new HashSet<>(Collections.singletonList("Coins"));
		HashSet<String> ignoredSources = new HashSet<>(Collections.singletonList("Zulrah"));
		LootSearchCriteria hidden = criteria("", SearchMode.SOURCE, LootSortOrder.MOST_RECENT,
			SourceTypeFilter.ALL, LootTrackerPriceType.GRAND_EXCHANGE, false, ignoredItems, ignoredSources);
		LootSearchCriteria shown = criteria("", SearchMode.SOURCE, LootSortOrder.MOST_RECENT,
			SourceTypeFilter.ALL, LootTrackerPriceType.GRAND_EXCHANGE, true, ignoredItems, ignoredSources);

		List<LootSearchResult> hiddenResults = LootSearch.search(sources, hidden);
		assertEquals(1, hiddenResults.size());
		assertEquals(1, hiddenResults.get(0).getVisibleItems().size());
		assertEquals("Dragon dart tip", hiddenResults.get(0).getVisibleItems().get(0).getName());
		assertEquals(2, LootSearch.search(sources, shown).size());
	}

	@Test
	public void highAlchemyModeChangesItemOrderingAndTotals()
	{
		LootSearchCriteria highAlchemy = criteria("vorkath", SearchMode.SOURCE, LootSortOrder.MOST_RECENT,
			SourceTypeFilter.ALL, LootTrackerPriceType.HIGH_ALCHEMY, true,
			Collections.emptySet(), Collections.emptySet());
		LootSearchResult result = LootSearch.search(sources, highAlchemy).get(0);

		assertEquals("Coins", result.getVisibleItems().get(0).getName());
		assertEquals(86_000, result.getTotalValue(LootTrackerPriceType.HIGH_ALCHEMY));
		assertSame(result.getSource().getItems(LootTrackerPriceType.HIGH_ALCHEMY),
			result.getSource().getItems(LootTrackerPriceType.HIGH_ALCHEMY));
	}

	@Test
	public void dropModeDoesNotMatchANameOfASource()
	{
		LootSource dragon = new LootSource("Dragon", "NPC", 1, Collections.singletonList(
			new LootItem(995, "Coins", 10, 1, 1)));

		assertTrue(LootSearch.search(Collections.singletonList(dragon), "dragon", SearchMode.DROP).isEmpty());
	}

	@Test
	public void dropSummaryAggregatesQuantityAndValueAcrossSources()
	{
		LootSource first = new LootSource("First", "NPC", 1, Collections.singletonList(
			new LootItem(995, "Coins", 10, 1, 1)));
		LootSource second = new LootSource("Second", "EVENT", 1, Collections.singletonList(
			new LootItem(995, "Coins", 20, 1, 1)));
		List<LootSearchResult> results = LootSearch.search(Arrays.asList(first, second), "coins", SearchMode.DROP);

		assertEquals(2, results.size());
		assertEquals(30, LootSearch.totalQuantity(results));
		assertEquals(30, LootSearch.totalValue(results, LootTrackerPriceType.GRAND_EXCHANGE));
	}

	private static LootSearchCriteria criteria(String query, SearchMode mode, LootSortOrder order,
		SourceTypeFilter sourceType, LootTrackerPriceType priceType, boolean showIgnored,
		java.util.Set<String> ignoredItems, java.util.Set<String> ignoredSources)
	{
		return new LootSearchCriteria(query, mode, order, sourceType, priceType, showIgnored,
			ignoredItems, ignoredSources);
	}
}

package com.searchableloottracker;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SearchableLootTrackerPluginSafetyTest
{
	@Test
	public void acceptsOnlyTheUnchangedActiveProfile()
	{
		assertTrue(SearchableLootTrackerPlugin.isExpectedProfile(
			true, 4L, 4L, "profile-a", "profile-a"));
	}

	@Test
	public void rejectsProfileAndLifecycleChanges()
	{
		assertFalse(SearchableLootTrackerPlugin.isExpectedProfile(
			false, 4L, 4L, "profile-a", "profile-a"));
		assertFalse(SearchableLootTrackerPlugin.isExpectedProfile(
			true, 4L, 5L, "profile-a", "profile-a"));
		assertFalse(SearchableLootTrackerPlugin.isExpectedProfile(
			true, 4L, 4L, "profile-a", "profile-b"));
		assertFalse(SearchableLootTrackerPlugin.isExpectedProfile(
			true, 4L, 4L, null, "profile-a"));
	}

	@Test
	public void generationRejectsAnAtoBtoATransition()
	{
		assertFalse(SearchableLootTrackerPlugin.isExpectedProfile(
			true, 10L, 12L, "profile-a", "profile-a"));
	}
}

package com.searchableloottracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import java.lang.reflect.Method;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

public class SearchableLootTrackerConfigTest
{
	private static final String REIMPORT_WARNING =
		"This deletes all Loot Tracker Extended history before copying the currently saved Loot Tracker history. RuneLite Loot Tracker history is not changed.";

	@Test
	public void usesAnOwnedConfigGroup()
	{
		ConfigGroup group = SearchableLootTrackerConfig.class.getAnnotation(ConfigGroup.class);

		assertEquals(SearchableLootTrackerConfig.GROUP, group.value());
		assertEquals("loottrackerextended", group.value());
	}

	@Test
	public void wikiFetchingIsOptInWithoutAWarning() throws Exception
	{
		SearchableLootTrackerConfig defaults = new SearchableLootTrackerConfig() { };
		Method method = SearchableLootTrackerConfig.class.getMethod("wikiDropRates");
		ConfigItem item = method.getAnnotation(ConfigItem.class);

		assertFalse(defaults.wikiDropRates());
		assertEquals("", item.warning());
	}

	@Test
	public void historyReimportIsAnExplicitDestructiveAction() throws Exception
	{
		SearchableLootTrackerConfig defaults = new SearchableLootTrackerConfig() { };
		Method method = SearchableLootTrackerConfig.class.getMethod("reimportHistory");
		ConfigItem item = method.getAnnotation(ConfigItem.class);

		assertFalse(defaults.reimportHistory());
		assertEquals("Re-import Loot Tracker history", item.name());
		assertEquals(REIMPORT_WARNING, item.warning());
	}
}

package com.searchableloottracker;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CardExpansionStateTest
{
	@Test
	public void searchExpansionDoesNotOverwriteCollapsedState()
	{
		CardExpansionState state = new CardExpansionState();
		state.registerDefaultExpanded("Vorkath");
		state.setExpanded("Vorkath", false);

		state.updateSearch("SOURCE:vork", Collections.singletonList("Vorkath"));
		assertTrue(state.isExpanded("Vorkath"));

		state.updateSearch(null, Collections.emptyList());
		assertFalse(state.isExpanded("Vorkath"));
	}

	@Test
	public void recreatingKnownCardDoesNotResetItsState()
	{
		CardExpansionState state = new CardExpansionState();
		state.registerDefaultExpanded("Zulrah");
		state.setExpanded("Zulrah", false);

		state.registerDefaultExpanded("Zulrah");

		assertFalse(state.isExpanded("Zulrah"));
	}

	@Test
	public void searchOnlyReopensCardsNewToThatQuery()
	{
		CardExpansionState state = new CardExpansionState();
		state.updateSearch("DROP:rune", Collections.singletonList("Vorkath"));
		state.setExpanded("Vorkath", false);

		state.updateSearch("DROP:rune", Arrays.asList("Vorkath", "Zulrah"));

		assertFalse(state.isExpanded("Vorkath"));
		assertTrue(state.isExpanded("Zulrah"));
	}

	@Test
	public void removingOneCardPreservesOtherExpansionChoices()
	{
		CardExpansionState state = new CardExpansionState();
		state.registerDefaultExpanded("Vorkath");
		state.registerDefaultExpanded("Zulrah");
		state.setExpanded("Zulrah", false);

		state.remove("Vorkath");

		assertFalse(state.isExpanded("Zulrah"));
	}
}

