			table.selectContext("Wilderness Slayer Cave").getTooltipLines("Rune 2h sword"));
	}

	@Test
	public void buildsNameOnlyAndNpcIdLookupUrls()
	{
		HttpUrl nameOnly = WikiDropRateService.buildUrl("Gnome woman", null);
		assertEquals("npc", nameOnly.queryParameter("type"));
		assertEquals("Gnome woman", nameOnly.queryParameter("name"));
		assertNull(nameOnly.queryParameter("id"));

		HttpUrl withId = WikiDropRateService.buildUrl("Gnome", 66);
		assertEquals("66", withId.queryParameter("id"));
		assertEquals("Gnome", withId.queryParameter("name"));

		WikiSourceResolver sourceResolver = new WikiSourceResolver(new Gson());
		WikiDropRateService service = new WikiDropRateService(new OkHttpClient(), sourceResolver);
		service.setEnabled(true);
		HttpUrl clueRewards = HttpUrl.parse(service.getDropTableUrl(
			"EVENT", "Clue Scroll (Medium)", null));
		assertEquals("Reward casket (medium)", clueRewards.queryParameter("name"));
		assertEquals("Rewards", clueRewards.fragment());
		assertNull(clueRewards.queryParameter("id"));

		HttpUrl barrowsRewards = HttpUrl.parse(service.getDropTableUrl(
			"EVENT", "Barrows", null));
		assertEquals("Chest (Barrows)", barrowsRewards.queryParameter("name"));
		assertEquals("Rewards", barrowsRewards.fragment());
		assertNull(barrowsRewards.queryParameter("id"));

		HttpUrl grotesqueGuardians = HttpUrl.parse(service.getDropTableUrl("NPC", "Dusk", 7888));
		assertEquals("Grotesque Guardians", grotesqueGuardians.queryParameter("name"));
		assertEquals("Drops", grotesqueGuardians.fragment());
		assertNull(grotesqueGuardians.queryParameter("id"));
		assertEquals("Grotesque Guardians",
			sourceResolver.resolve("NPC", " dusk ", 7888).getPageTitle());
		assertEquals("Vorkath", sourceResolver.resolve("NPC", "Vorkath", 8061).getPageTitle());

		WikiSourceResolution wilderness = sourceResolver.resolve(
			"NPC", "Greater demon", 7871);
		assertEquals("Greater demon", wilderness.getPageTitle());
		assertEquals(Integer.valueOf(7871), wilderness.getNpcId());
		assertEquals("Wilderness Slayer Cave", wilderness.getTableContext());

		WikiSourceResolution waterbirth = sourceResolver.resolve("NPC", "Dagannoth", 2259);
		assertEquals("Dagannoth (Waterbirth Island)", waterbirth.getPageTitle());
		assertEquals("Level 88", waterbirth.getTableContext());
		assertNull(waterbirth.getNpcId());
		assertEquals(2, sourceResolver.resolveNameCandidates(
			"NPC", "Dagannoth").size());

		HttpUrl mixedWaterbirth = HttpUrl.parse(service.getDropTableUrlForVariants(
			"NPC", "Dagannoth", new LinkedHashSet<>(Arrays.asList(2259, 3185))));
		assertEquals("Dagannoth (Waterbirth Island)", mixedWaterbirth.queryParameter("name"));
		assertNull(mixedWaterbirth.fragment());
	}

	private static String dropTable(String item, String quantity, String rarity)
	{
		return "<table class='item-drops'><tr><th>Item</th><th>Quantity</th><th>Rarity</th></tr>"
			+ "<tr><td>" + item + "</td><td>" + quantity + "</td><td>" + rarity
			+ "</td></tr></table>";
	}
}

package com.searchableloottracker.wiki;

import java.io.File;
import java.util.Collections;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class WikiDropTableDiskCacheTest
{
	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void persistsParsedDropTablesAcrossCacheInstances() throws Exception
	{
		File directory = temporaryFolder.newFolder("wiki-cache");
		WikiDropTableDiskCache first = new WikiDropTableDiskCache(directory, 10);
		first.put("guard:1", table("Coins", "10", "1/2"));

		WikiDropTable restored = new WikiDropTableDiskCache(directory, 10).get("guard:1");

		assertNotNull(restored);
		assertEquals(Collections.singletonList("1/2 (x10)"), restored.getTooltipLines("Coins"));
	}

	@Test
	public void clearingRemovesPersistentEntries() throws Exception
	{
		WikiDropTableDiskCache cache = new WikiDropTableDiskCache(
			temporaryFolder.newFolder("clear-cache"), 10);
		cache.put("guard:1", table("Coins", "10", "1/2"));
		cache.clear();

		assertNull(cache.get("guard:1"));
	}

	@Test
	public void fullCacheEvictsInsteadOfRejectingNewTables() throws Exception
	{
		File directory = temporaryFolder.newFolder("bounded-cache");
		WikiDropTableDiskCache cache = new WikiDropTableDiskCache(directory, 2);
		cache.put("first", table("Coins", "1", "1/2"));
		cache.put("second", table("Coins", "2", "1/3"));
		cache.put("third", table("Coins", "3", "1/4"));

		File[] entries = directory.listFiles((ignored, name) -> name.endsWith(".table"));
		assertNotNull(entries);
		assertEquals(2, entries.length);
		assertNotNull(cache.get("third"));
	}

	private static WikiDropTable table(String item, String quantity, String rate)
	{
		return new WikiDropTable(Collections.singletonMap(item.toLowerCase(),
			Collections.singletonList(new WikiDropRate(quantity, rate, ""))));
	}
}

