package com.searchableloottracker.wiki;

import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.Comparator;
import lombok.extern.slf4j.Slf4j;

/**
 * Versioned, bounded, best-effort disk cache for parsed Wiki tables. Filenames
 * are hashes of lookup keys, so untrusted source names never become paths.
 */
@Slf4j
final class WikiDropTableDiskCache
{
	private static final int MAGIC = 0x4c544557;
	private static final int VERSION = 3;
	private static final String EXTENSION = ".table";

	private final File directory;
	private final int maximumEntries;
	private long lastAccessTimestamp;

	WikiDropTableDiskCache(File directory, int maximumEntries)
	{
		this.directory = directory;
		this.maximumEntries = maximumEntries;
	}

	synchronized WikiDropTable get(String key)
	{
		if (directory == null)
		{
			return null;
		}
		File file = fileFor(key);
		if (!file.isFile())
		{
			return null;
		}
		try (DataInputStream input = new DataInputStream(
			new BufferedInputStream(new FileInputStream(file))))
		{
			if (input.readInt() != MAGIC || input.readInt() != VERSION)
			{
				throw new IOException("Unsupported cache format");
			}
			WikiDropTable table = WikiDropTable.read(input);
			file.setLastModified(nextAccessTimestamp());
			return table;
		}
		catch (IOException | RuntimeException exception)
		{
			log.debug("Unable to read cached Wiki drop table", exception);
			if (!file.delete())
			{
				log.debug("Unable to remove invalid Wiki drop table cache file {}", file);
			}
			return null;
		}
	}

	synchronized void put(String key, WikiDropTable table)
	{
		if (directory == null || maximumEntries <= 0 || (!directory.isDirectory() && !directory.mkdirs()))
		{
			return;
		}
		File target = fileFor(key);
		File temporary = new File(directory, target.getName() + ".tmp");
		try (DataOutputStream output = new DataOutputStream(
			new BufferedOutputStream(new FileOutputStream(temporary))))
		{
			output.writeInt(MAGIC);
			output.writeInt(VERSION);
			table.write(output);
		}
		catch (IOException exception)
		{
			log.debug("Unable to write cached Wiki drop table", exception);
			temporary.delete();
			return;
		}

		try
		{
			// Install only a complete serialized table. A failed write leaves no
			// partially readable target entry behind.
			Files.move(temporary.toPath(), target.toPath(), StandardCopyOption.REPLACE_EXISTING);
			target.setLastModified(nextAccessTimestamp());
			prune();
		}
		catch (IOException exception)
		{
			log.debug("Unable to install cached Wiki drop table", exception);
			temporary.delete();
		}
	}

	synchronized void clear()
	{
		if (directory == null)
		{
			return;
		}
		File[] files = directory.listFiles((ignored, name) ->
			name.endsWith(EXTENSION) || name.endsWith(EXTENSION + ".tmp"));
		if (files == null)
		{
			return;
		}
		for (File file : files)
		{
			if (!file.delete())
			{
				log.debug("Unable to remove Wiki drop table cache file {}", file);
			}
		}
	}

	private void prune()
	{
		File[] files = directory.listFiles((ignored, name) -> name.endsWith(EXTENSION));
		if (files == null || files.length <= maximumEntries)
		{
			return;
		}
		Arrays.sort(files, Comparator.comparingLong(File::lastModified));
		for (int index = 0; index < files.length - maximumEntries; index++)
		{
			if (!files[index].delete())
			{
				log.debug("Unable to prune Wiki drop table cache file {}", files[index]);
			}
		}
	}

	private File fileFor(String key)
	{
		return new File(directory, sha256(key) + EXTENSION);
	}

	private long nextAccessTimestamp()
	{
		lastAccessTimestamp = Math.max(System.currentTimeMillis(), lastAccessTimestamp + 1);
		return lastAccessTimestamp;
	}

	private static String sha256(String value)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256")
				.digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder encoded = new StringBuilder(digest.length * 2);
			for (byte part : digest)
			{
				encoded.append(String.format("%02x", part & 0xff));
			}
			return encoded.toString();
		}
		catch (NoSuchAlgorithmException exception)
		{
			throw new IllegalStateException("SHA-256 is unavailable", exception);
		}
	}
}

package com.searchableloottracker.wiki;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

/**
 * Maps RuneLite source identities to the Wiki page that owns their drops. Most sources pass
 * through unchanged; the bundled data file contains the exceptional ownership relationships.
 */
final class WikiSourceResolver
{
	private static final String OVERRIDES_RESOURCE = "/wiki-source-overrides.json";
	private static final Pattern CLUE_SOURCE = Pattern.compile(
		"(?i)^clue scroll \\((beginner|easy|medium|hard|elite|master)\\)$");
	private final List<OverrideEntry> overrides;

	@Inject
	WikiSourceResolver(Gson gson)
	{
		overrides = loadOverrides(gson);
	}

	WikiSourceResolution resolve(String sourceType, String sourceName, Integer npcId)
	{
		String trimmedName = sourceName.trim();
		String normalizedType = sourceType.trim().toUpperCase(Locale.ENGLISH);
		Integer validNpcId = npcId != null && npcId >= 0 ? npcId : null;
		OverrideEntry best = null;
		for (OverrideEntry candidate : overrides)
		{
			if (candidate.matches(normalizedType, trimmedName, validNpcId)
				&& (best == null || candidate.isMoreSpecificThan(best)))
			{
				best = candidate;
			}
		}
		if (best != null)
		{
			return new WikiSourceResolution(best.pageTitle, best.section,
				best.retainNpcId ? validNpcId : null, best.tableContext);
		}

		Matcher clue = CLUE_SOURCE.matcher(trimmedName);
		if (clue.matches())
		{
			return new WikiSourceResolution(
				"Reward casket (" + clue.group(1).toLowerCase(Locale.ENGLISH) + ")",
				"Rewards", null, null);
		}
		return new WikiSourceResolution(trimmedName, "Drops", validNpcId, null);
	}

	/**
	 * Returns every plausible owner page for ID-less history. Exact-ID overrides may opt into this
	 * list when RuneLite groups several independently documented monsters under one display name.
	 */
	List<WikiSourceResolution> resolveNameCandidates(String sourceType, String sourceName)
	{
		String trimmedName = sourceName.trim();
		String normalizedType = sourceType.trim().toUpperCase(Locale.ENGLISH);
		Map<String, WikiSourceResolution> candidates = new LinkedHashMap<>();
		WikiSourceResolution primary = resolve(sourceType, sourceName, null);
		candidates.put(primary.getPageTitle().toLowerCase(Locale.ENGLISH), primary);
		for (OverrideEntry entry : overrides)
		{
			if (entry.includeForNameLookup && entry.matchesSource(normalizedType, trimmedName))
			{
				WikiSourceResolution candidate = new WikiSourceResolution(
					entry.pageTitle, entry.section, null, null);
				candidates.putIfAbsent(
					candidate.getPageTitle().toLowerCase(Locale.ENGLISH), candidate);
			}
		}
		return Collections.unmodifiableList(new ArrayList<>(candidates.values()));
	}

	boolean isRegisteredContext(String heading)
	{
		if (heading == null || heading.trim().isEmpty())
		{
			return false;
		}
		for (OverrideEntry entry : overrides)
		{
			if (entry.tableContext != null && entry.tableContext.equalsIgnoreCase(heading.trim()))
			{
				return true;
			}
		}
		return false;
	}

	private static List<OverrideEntry> loadOverrides(Gson gson)
	{
		try (InputStream input = WikiSourceResolver.class.getResourceAsStream(OVERRIDES_RESOURCE))
		{
			if (input == null)
			{
				throw new IllegalStateException("Missing " + OVERRIDES_RESOURCE);
			}
			OverrideEntry[] entries = gson.fromJson(
				new InputStreamReader(input, StandardCharsets.UTF_8), OverrideEntry[].class);
			List<OverrideEntry> loaded = new ArrayList<>();
			if (entries != null)
			{
				Collections.addAll(loaded, entries);
			}
			for (OverrideEntry entry : loaded)
			{
				entry.validate();
			}
			return Collections.unmodifiableList(loaded);
		}
		catch (Exception exception)
		{
			throw new ExceptionInInitializerError(exception);
		}
	}

	private static final class OverrideEntry
	{
		private String sourceType;
		private String sourceName;
		private int[] npcIds;
		private String pageTitle;
		private String section = "Drops";
		private boolean retainNpcId;
		private String tableContext;
		private boolean includeForNameLookup;

		private void validate()
		{
			if (sourceType == null || sourceName == null || pageTitle == null || section == null
				|| sourceType.trim().isEmpty() || sourceName.trim().isEmpty()
				|| pageTitle.trim().isEmpty() || section.trim().isEmpty())
			{
				throw new IllegalStateException("Incomplete Wiki source override");
			}
		}

		private boolean matches(String type, String name, Integer npcId)
		{
			if (!matchesSource(type, name))
			{
				return false;
			}
			if (npcIds == null || npcIds.length == 0)
			{
				return true;
			}
			if (npcId == null)
			{
				return false;
			}
			for (int candidate : npcIds)
			{
				if (candidate == npcId)
				{
					return true;
				}
			}
			return false;
		}

		private boolean matchesSource(String type, String name)
		{
			return sourceType.trim().equalsIgnoreCase(type)
				&& sourceName.trim().equalsIgnoreCase(name);
		}

		private boolean isMoreSpecificThan(OverrideEntry other)
		{
			return npcIds != null && npcIds.length > 0
				&& (other.npcIds == null || other.npcIds.length == 0);
		}
	}
}

package com.searchableloottracker.wiki;

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;

/**
 * Converts the Wiki's rendered item-drop tables into the small immutable
 * representation used by tooltips. Parsing rendered markup avoids coupling
 * the rest of the plugin to Wiki templates and their intermediate notation.
 */
final class WikiDropTableParser
{
	private WikiDropTableParser()
	{
	}

	static WikiDropTable parse(String html)
	{
		return parse(Jsoup.parse(html));
	}

	static WikiDropTable parse(InputStream html) throws IOException
	{
		return parse(Jsoup.parse(html, null, ""), null);
	}

	static WikiDropTable parse(InputStream html, WikiSourceResolver sourceResolver) throws IOException
	{
		return parse(Jsoup.parse(html, null, ""), sourceResolver);
	}

	private static WikiDropTable parse(Document document)
	{
		return parse(document, null);
	}

	private static WikiDropTable parse(Document document, WikiSourceResolver sourceResolver)
	{
		Map<String, List<WikiDropRate>> collectedRates = new LinkedHashMap<>();
		String levelTwo = "";
		String levelThree = "";
		String levelFour = "";
		for (Element element : document.select("h2, h3, h4, table.item-drops"))
		{
			if (element.is("h2"))
			{
				levelTwo = cleanHeading(element.text());
				levelThree = "";
				levelFour = "";
			}
			else if (element.is("h3"))
			{
				levelThree = cleanHeading(element.text());
				levelFour = "";
			}
			else if (element.is("h4"))
			{
				levelFour = cleanHeading(element.text());
			}
			else
			{
				parseTable(element, collectedRates,
					tableLabel(levelTwo, levelThree, levelFour),
					contextLabel(levelTwo, levelThree, levelFour, sourceResolver));
			}
		}
		return new WikiDropTable(collectedRates);
	}

	private static void parseTable(Element table, Map<String, List<WikiDropRate>> rates,
		String tableLabel, String contextLabel)
	{
		TableColumns columns = findColumns(table.selectFirst("tr:has(th)"));

		for (Element row : table.select("tr"))
		{
			Elements cells = row.select("td");
			if (!columns.areAvailable(cells.size()))
			{
				continue;
			}

			String itemName = parseItemName(cells.get(columns.item));
			String quantity = clean(cells.get(columns.quantity).text());
			String rarity = parseRarity(cells.get(columns.rarity));
			if (itemName.isEmpty() || rarity.isEmpty())
			{
				continue;
			}
			WikiDropRate rate = new WikiDropRate(quantity, rarity, tableLabel, contextLabel);
			List<WikiDropRate> itemRates = rates.computeIfAbsent(
				WikiDropTable.normalize(itemName), ignored -> new ArrayList<>());
			if (!itemRates.contains(rate))
			{
				itemRates.add(rate);
			}
		}
	}

	private static String parseItemName(Element cell)
	{
		for (Element link : cell.select("a"))
		{
			String linkedName = clean(link.text());
			if (!linkedName.isEmpty())
			{
				return linkedName;
			}
		}
		return clean(cell.text()).replaceFirst("(?i)\\s*\\(m\\)$", "");
	}

	private static TableColumns findColumns(Element header)
	{
		int item = 0;
		int quantity = 1;
		int rarity = 2;
		if (header == null)
		{
			return new TableColumns(item, quantity, rarity);
		}

		int column = 0;
		for (Element heading : header.select("th"))
		{
			int span = parsePositiveInt(heading.attr("colspan"), 1);
			String label = clean(heading.text()).toLowerCase();
			if (label.equals("item") || label.equals("drop"))
			{
				item = column + span - 1;
			}
			else if (label.contains("quantity") || label.contains("amount"))
			{
				quantity = column;
			}
			else if (label.contains("rarity") || label.contains("chance") || label.contains("rate"))
			{
				rarity = column;
			}
			column += span;
		}
		return new TableColumns(item, quantity, rarity);
	}

	private static String parseRarity(Element cell)
	{
		Elements dropRates = cell.select("[data-drop-fraction]");
		if (dropRates.isEmpty())
		{
			return clean(cell.text());
		}

		List<String> formatted = new ArrayList<>();
		for (Element dropRate : dropRates)
		{
			String fraction = clean(dropRate.attr("data-drop-fraction"));
			String oneOver = clean(dropRate.attr("data-drop-oneover"));
			String display = startsWithOneOver(fraction) || oneOver.isEmpty() ? fraction : oneOver;
			if (!display.isEmpty() && !formatted.contains(display))
			{
				formatted.add(display);
			}
		}
		return String.join("; ", formatted);
	}

	private static boolean startsWithOneOver(String rate)
	{
		return rate.matches("^1\\s*/.*");
	}

	private static String cleanHeading(String heading)
	{
		return clean(heading).replaceFirst("(?i)\\s*\\[edit(?: \\| edit source)?]$", "");
	}

	private static String tableLabel(String levelTwo, String levelThree, String levelFour)
	{
		String local = !levelFour.isEmpty() ? levelFour
			: !levelThree.isEmpty() ? levelThree : levelTwo;
		String localLower = local.toLowerCase();
		if (localLower.contains("rare") && localLower.contains("gem")
			&& localLower.contains("table"))
		{
			return "Rare/Gem Table";
		}
		if (localLower.contains("rare") && localLower.contains("table"))
		{
			return "Rare Drop Table";
		}
		if (localLower.contains("gem") && localLower.contains("table"))
		{
			return "Gem Drop Table";
		}

		if (localLower.contains("wilderness slayer tertiary"))
		{
			return "Wilderness Slayer";
		}
		if (localLower.contains("drop table")
			|| (localLower.endsWith("tertiary") && !"tertiary".equals(localLower)))
		{
			return local;
		}
		return "";
	}

	/**
	 * Finds the variant/location heading that owns a table independently of its local category.
	 * Wiki pages commonly nest "Weapons and armour" beneath headings such as "Standard and
	 * Catacombs of Kourend"; retaining both levels prevents distinct variant rates from collapsing
	 * into one apparently ambiguous table.
	 */
	private static String contextLabel(String levelTwo, String levelThree, String levelFour,
		WikiSourceResolver sourceResolver)
	{
		String major = variantLabel(levelTwo, sourceResolver);
		if (!major.isEmpty() && tableLabel(levelTwo, "", "").isEmpty())
		{
			return major;
		}

		String secondary = variantLabel(levelThree, sourceResolver);
		if (!secondary.isEmpty() && tableLabel("", levelThree, "").isEmpty())
		{
			return secondary;
		}

		String tertiary = variantLabel(levelFour, sourceResolver);
		if (!tertiary.isEmpty() && tableLabel("", "", levelFour).isEmpty())
		{
			return tertiary;
		}
		return "";
	}

	private static String stripDropSuffix(String heading)
	{
		return heading.replaceFirst("(?i)^(?:drops|rewards)\\s*\\((.+)\\)$", "$1")
			.replaceFirst("(?i)\\s+(?:drops|rewards)$", "").trim();
	}

	private static String variantLabel(String heading, WikiSourceResolver sourceResolver)
	{
		String candidate = stripDropSuffix(heading);
		String normalized = candidate.toLowerCase(Locale.ENGLISH);
		boolean structuralVariant = normalized.startsWith("level ")
			|| normalized.contains("standard")
			|| normalized.contains("wilderness slayer cave")
			|| normalized.contains("catacombs of kourend");
		return structuralVariant
			|| (sourceResolver != null && sourceResolver.isRegisteredContext(candidate))
			? candidate : "";
	}

	private static int parsePositiveInt(String value, int fallback)
	{
		try
		{
			int parsed = Integer.parseInt(value);
			return parsed > 0 ? parsed : fallback;
		}
		catch (NumberFormatException ignored)
		{
			return fallback;
		}
	}

	private static String clean(String value)
	{
		return value.replaceAll("\\[[^]]*]", "")
			.replace('\u00a0', ' ')
			.trim()
			.replaceAll("\\s+", " ");
	}

	private static final class TableColumns
	{
		private final int item;
		private final int quantity;
		private final int rarity;

		private TableColumns(int item, int quantity, int rarity)
		{
			this.item = item;
			this.quantity = quantity;
			this.rarity = rarity;
		}

		private boolean areAvailable(int cellCount)
		{
			return cellCount > Math.max(item, Math.max(quantity, rarity));
		}
	}
}

package com.searchableloottracker.wiki;

import java.io.DataInput;
import java.io.DataOutput;
import java.io.IOException;
import java.util.Locale;
import java.util.Objects;

/** A single quantity/rate combination as rendered in a Wiki drop-table row. */
final class WikiDropRate
{
	private final String quantity;
	private final String rate;
	private final String tableLabel;
	private final String contextLabel;

	WikiDropRate(String quantity, String rate, String tableLabel)
	{
		this(quantity, rate, tableLabel, "");
	}

	WikiDropRate(String quantity, String rate, String tableLabel, String contextLabel)
	{
		this.quantity = quantity;
		this.rate = rate;
		this.tableLabel = tableLabel;
		this.contextLabel = contextLabel;
	}

	String getTableLabel()
	{
		return tableLabel;
	}

	String getContextLabel()
	{
		return contextLabel;
	}

	String getTableIdentity()
	{
		return contextLabel.toLowerCase(Locale.ENGLISH) + '\0'
			+ tableLabel.toLowerCase(Locale.ENGLISH);
	}

	WikiDropRate withContextPrefix(String prefix)
	{
		String prefixedContext = contextLabel.isEmpty()
			? prefix : prefix + " - " + contextLabel;
		return new WikiDropRate(quantity, rate, tableLabel, prefixedContext);
	}

	String format()
	{
		StringBuilder formatted = new StringBuilder(rate);
		if (!quantity.isEmpty() && !"N/A".equalsIgnoreCase(quantity))
		{
			formatted.append(" (x").append(formatQuantity(quantity)).append(')');
		}
		String displayLabel = tableLabel;
		if (!contextLabel.isEmpty() && !contextLabel.equalsIgnoreCase(tableLabel))
		{
			displayLabel = displayLabel.isEmpty()
				? contextLabel : displayLabel + " - " + contextLabel;
		}
		if (!displayLabel.isEmpty())
		{
			formatted.append(" (").append(displayLabel).append(')');
		}
		return formatted.toString();
	}

	private static String formatQuantity(String value)
	{
		// Wiki typography uses several Unicode dash variants; RuneLite's small
		// tooltip font renders some of them too low, so display a plain hyphen.
		return value.replace(" (noted)", " noted")
			.replace('\u2010', '-')
			.replace('\u2011', '-')
			.replace('\u2012', '-')
			.replace('\u2013', '-')
			.replace('\u2014', '-')
			.replace('\u2212', '-');
	}

	void write(DataOutput output) throws IOException
	{
		output.writeUTF(quantity);
		output.writeUTF(rate);
		output.writeUTF(tableLabel);
		output.writeUTF(contextLabel);
	}

	static WikiDropRate read(DataInput input) throws IOException
	{
		return new WikiDropRate(input.readUTF(), input.readUTF(), input.readUTF(), input.readUTF());
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof WikiDropRate))
		{
			return false;
		}
		WikiDropRate rate = (WikiDropRate) other;
		return quantity.equals(rate.quantity)
			&& this.rate.equals(rate.rate)
			&& tableLabel.equals(rate.tableLabel)
			&& contextLabel.equals(rate.contextLabel);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(quantity, rate, tableLabel, contextLabel);
	}
}

package com.searchableloottracker.wiki;

import java.io.File;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Queue;
import java.util.Set;
import java.util.concurrent.CancellationException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import net.runelite.client.RuneLite;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Resolves one complete source variant at a time and shares it between all item tooltips for that
 * source. Variant IDs mapped to the same Wiki context coalesce behind one future. Disk reads and
 * HTTP callbacks stay off the client thread.
 */
public final class WikiDropRateService
{
	private static final String LOOKUP_URL = "https://oldschool.runescape.wiki/w/Special:Lookup";
	private static final String USER_AGENT =
		"Loot Tracker Extended (https://github.com/Suffdev/loot-tracker-extended)";
	private static final int MAX_CONCURRENT_REQUESTS = 2;
	private static final int MAX_LOOKUPS_PER_SOURCE = 16;
	private static final int MAX_PENDING_REQUESTS = 64;
	private static final int MAX_CACHE_ENTRIES = 256;
	private static final int MAX_DISK_CACHE_ENTRIES = 1024;
	private static final int MAX_RESPONSE_BYTES = 4 * 1024 * 1024;
	private final OkHttpClient httpClient;
	private final WikiDropTableDiskCache diskCache;
	private final WikiSourceResolver sourceResolver;
	// A source card can request several item tooltips at once. Coalescing here
	// prevents each item from downloading and parsing the same NPC page.
	private final Map<LookupKey, CompletableFuture<WikiDropTable>> inFlight = new ConcurrentHashMap<>();
	private final Set<Call> activeCalls = Collections.newSetFromMap(new ConcurrentHashMap<>());
	private final AtomicLong cacheGeneration = new AtomicLong();
	private final Map<LookupKey, WikiDropTable> cache = new LinkedHashMap<LookupKey, WikiDropTable>(
		MAX_CACHE_ENTRIES + 1, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<LookupKey, WikiDropTable> eldest)
		{
			return size() > MAX_CACHE_ENTRIES;
		}
	};
	private final Queue<PendingLookup> pendingLookups = new ArrayDeque<>();
	private int activeRequests;
	// Network-backed features must remain inert until the user explicitly opts in.
	private volatile boolean enabled;

	@Inject
	public WikiDropRateService(OkHttpClient httpClient, WikiSourceResolver sourceResolver)
	{
		this(httpClient, new WikiDropTableDiskCache(
			new File(new File(RuneLite.RUNELITE_DIR, "loot-tracker-extended"), "wiki-cache"),
			MAX_DISK_CACHE_ENTRIES), sourceResolver);
	}

	WikiDropRateService(OkHttpClient httpClient, WikiDropTableDiskCache diskCache,
		WikiSourceResolver sourceResolver)
	{
		this.httpClient = httpClient;
		this.diskCache = diskCache;
		this.sourceResolver = sourceResolver;
	}

	public CompletableFuture<WikiDropTable> lookup(String sourceType, String sourceName, Integer npcId)
	{
		if (!enabled)
		{
			return failedLookup("Wiki drop rates are disabled");
		}
		if (!canLookup(sourceType, sourceName))
		{
			return failedLookup("Wiki lookup is not permitted for this loot source");
		}
		WikiSourceResolution resolution = sourceResolver.resolve(sourceType, sourceName, npcId);
		return lookup(resolution);
	}

	private CompletableFuture<WikiDropTable> lookup(WikiSourceResolution resolution)
	{
		String lookupName = resolution.getPageTitle();
		Integer lookupNpcId = resolution.getNpcId();
		LookupKey cacheKey = new LookupKey(
			lookupName, lookupNpcId, resolution.getTableContext());
		WikiDropTable cached = getCached(cacheKey);
		if (cached != null)
		{
			return CompletableFuture.completedFuture(cached);
		}

		CompletableFuture<WikiDropTable> result = new CompletableFuture<>();
		long generation = cacheGeneration.get();
		CompletableFuture<WikiDropTable> existing = inFlight.putIfAbsent(cacheKey, result);
		if (existing != null)
		{
			if (existing.isCompletedExceptionally() && inFlight.remove(cacheKey, existing))
			{
				return lookup(resolution);
			}
			return existing;
		}

		result.whenComplete((table, error) ->
		{
			// A cache clear/disable increments the generation so late HTTP
			// completions cannot silently repopulate an invalidated cache.
			if (error == null && generation == cacheGeneration.get())
			{
				cache(cacheKey, table);
			}
			// Publish a successful value to memory before removing the in-flight marker. A caller
			// released by CompletableFuture completion can otherwise slip between those operations
			// and start a duplicate request.
			inFlight.remove(cacheKey, result);
			if (error == null && generation == cacheGeneration.get())
			{
				diskCache.put(cacheKey.persistentKey(), table);
			}
		});
		// Recheck after registering inFlight: another completion may have
		// populated memory between the first cache read and putIfAbsent.
		cached = getCached(cacheKey);
		if (cached != null)
		{
			result.complete(cached);
		}
		else
		{
			httpClient.dispatcher().executorService().execute(() ->
			{
				if (!enabled || generation != cacheGeneration.get())
				{
					result.completeExceptionally(new CancellationException("Wiki drop-rate request invalidated"));
					return;
				}
				WikiDropTable persisted = diskCache.get(cacheKey.persistentKey());
				if (!enabled || generation != cacheGeneration.get())
				{
					result.completeExceptionally(new CancellationException("Wiki drop-rate request invalidated"));
					return;
				}
				if (persisted != null)
				{
					result.complete(persisted);
				}
				else
				{
					enqueue(new PendingLookup(lookupName, lookupNpcId,
						resolution.getTableContext(), generation, result));
				}
			});
		}
		return result;
	}

	/** Resolves and combines every concrete variant represented by a name-grouped loot source. */
	public CompletableFuture<WikiDropTable> lookupVariants(String sourceType, String sourceName,
		Set<Integer> npcIds)
	{
		return lookupVariants(sourceType, sourceName, npcIds, npcIds == null || npcIds.isEmpty());
	}

	/**
	 * Resolves known variants plus broad candidates when older kills in the aggregate have no ID.
	 * Plans are deduplicated before any futures are created and fall back to bounded name lookup if
	 * the source contains an unreasonable number of distinct variants.
	 */
	public CompletableFuture<WikiDropTable> lookupVariants(String sourceType, String sourceName,
		Set<Integer> npcIds, boolean hasUnknownNpcVariants)
	{
		if (!enabled || !canLookup(sourceType, sourceName))
		{
			return lookup(sourceType, sourceName, (Integer) null);
		}

		Map<LookupKey, WikiSourceResolution> plans = new LinkedHashMap<>();
		Map<String, Boolean> broadPages = new LinkedHashMap<>();
		if (hasUnknownNpcVariants || npcIds == null || npcIds.isEmpty())
		{
			addNameCandidates(sourceType, sourceName, plans, broadPages);
		}

		if (npcIds != null)
		{
			for (Integer npcId : npcIds)
			{
				WikiSourceResolution resolution = sourceResolver.resolve(sourceType, sourceName, npcId);
				if (!broadPages.containsKey(normalizePage(resolution.getPageTitle())))
				{
					plans.putIfAbsent(keyFor(resolution), resolution);
				}
				if (plans.size() > MAX_LOOKUPS_PER_SOURCE)
				{
					plans.clear();
					broadPages.clear();
					addNameCandidates(sourceType, sourceName, plans, broadPages);
					break;
				}
			}
		}
		return executePlans(new ArrayList<>(plans.values()));
	}

	private void addNameCandidates(String sourceType, String sourceName,
		Map<LookupKey, WikiSourceResolution> plans, Map<String, Boolean> broadPages)
	{
		for (WikiSourceResolution candidate :
			sourceResolver.resolveNameCandidates(sourceType, sourceName))
		{
			plans.putIfAbsent(keyFor(candidate), candidate);
			broadPages.put(normalizePage(candidate.getPageTitle()), Boolean.TRUE);
		}
	}

	private CompletableFuture<WikiDropTable> executePlans(List<WikiSourceResolution> plans)
	{
		if (plans.isEmpty())
		{
			return failedLookup("No Wiki lookup plan is available for this source");
		}
		Map<String, Boolean> pages = new LinkedHashMap<>();
		List<CompletableFuture<LookupResult>> attempts = new ArrayList<>(plans.size());
		for (WikiSourceResolution plan : plans)
		{
			pages.put(normalizePage(plan.getPageTitle()), Boolean.TRUE);
			attempts.add(lookup(plan).handle(LookupResult::new));
		}
		boolean labelPages = pages.size() > 1;
		CompletableFuture<?>[] futures = attempts.toArray(new CompletableFuture<?>[0]);
		return CompletableFuture.allOf(futures).thenApply(ignored ->
		{
			List<WikiDropTable> tables = new ArrayList<>(attempts.size());
			Throwable firstFailure = null;
			for (int index = 0; index < attempts.size(); index++)
			{
				LookupResult attempt = attempts.get(index).join();
				if (attempt.table != null)
				{
					tables.add(labelPages ? attempt.table.withContextPrefix(
						plans.get(index).getPageTitle()) : attempt.table);
				}
				else if (firstFailure == null)
				{
					firstFailure = attempt.error;
				}
			}
			if (tables.isEmpty())
			{
				throw new CompletionException(firstFailure == null
					? new IOException("All Wiki lookups failed") : firstFailure);
			}
			return WikiDropTable.merge(tables);
		});
	}

	private static LookupKey keyFor(WikiSourceResolution resolution)
	{
		return new LookupKey(resolution.getPageTitle(), resolution.getNpcId(),
			resolution.getTableContext());
	}

	private static String normalizePage(String pageTitle)
	{
		return pageTitle.trim().toLowerCase(Locale.ENGLISH);
	}

	private static CompletableFuture<WikiDropTable> failedLookup(String message)
	{
		CompletableFuture<WikiDropTable> failed = new CompletableFuture<>();
		failed.completeExceptionally(new CancellationException(message));
		return failed;
	}

	/**
	 * Allows only RuneLite source categories whose names identify game content. In particular,
	 * PLAYER records contain the other player's display name and must never reach the Wiki.
	 */
	public boolean canLookup(String sourceType, String sourceName)
	{
		if (sourceType == null || sourceName == null || sourceName.trim().isEmpty())
		{
			return false;
		}
		switch (sourceType.trim().toUpperCase(Locale.ENGLISH))
		{
			case "NPC":
			case "PICKPOCKET":
			case "EVENT":
				return true;
			default:
				return false;
		}
	}

	private WikiDropTable getCached(LookupKey key)
	{
		synchronized (cache)
		{
			return cache.get(key);
		}
	}

	private void cache(LookupKey key, WikiDropTable table)
	{
		synchronized (cache)
		{
			cache.put(key, table);
		}
	}

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
		if (!enabled)
		{
			invalidateRequests();
		}
	}

	public void clearCache()
	{
		invalidateRequests();
		synchronized (cache)
		{
			cache.clear();
		}
		diskCache.clear();
	}

	private void invalidateRequests()
	{
		cacheGeneration.incrementAndGet();
		CancellationException cancelled = new CancellationException("Wiki drop-rate request invalidated");
		synchronized (this)
		{
			PendingLookup pending;
			while ((pending = pendingLookups.poll()) != null)
			{
				pending.result.completeExceptionally(cancelled);
			}
		}
		for (Call call : activeCalls)
		{
			call.cancel();
		}
	}

	int cachedEntryCount()
	{
		synchronized (cache)
		{
			return cache.size();
		}
	}

	public String getDropTableUrl(String sourceType, String sourceName, Integer npcId)
	{
		if (!enabled || !canLookup(sourceType, sourceName))
		{
			throw new IllegalStateException("Wiki lookup is disabled or not permitted for this loot source");
		}
		WikiSourceResolution resolution = sourceResolver.resolve(sourceType, sourceName, npcId);
		String lookupName = resolution.getPageTitle();
		Integer lookupNpcId = resolution.getNpcId();
		return buildUrl(lookupName, lookupNpcId).newBuilder()
			.fragment(resolution.getSection())
			.build()
			.toString();
	}

	public String getDropTableUrlForVariants(String sourceType, String sourceName, Set<Integer> npcIds)
	{
		if (npcIds == null || npcIds.isEmpty())
		{
			return getDropTableUrl(sourceType, sourceName, (Integer) null);
		}
		Integer representative = npcIds.iterator().next();
		WikiSourceResolution first = sourceResolver.resolve(sourceType, sourceName, representative);
		boolean mixedContexts = false;
		for (Integer npcId : npcIds)
		{
			WikiSourceResolution candidate = sourceResolver.resolve(sourceType, sourceName, npcId);
			if (!first.getPageTitle().equals(candidate.getPageTitle()))
			{
				return getDropTableUrl(sourceType, sourceName, (Integer) null);
			}
			mixedContexts |= !first.getSection().equals(candidate.getSection())
				|| !Objects.equals(first.getTableContext(), candidate.getTableContext());
		}
		if (mixedContexts)
		{
			return buildUrl(first.getPageTitle(), null).toString();
		}
		return getDropTableUrl(sourceType, sourceName, representative);
	}

	private synchronized void enqueue(PendingLookup lookup)
	{
		if (!enabled || lookup.generation != cacheGeneration.get())
		{
			lookup.result.completeExceptionally(new CancellationException("Wiki drop-rate request invalidated"));
			return;
		}
		if (pendingLookups.size() >= MAX_PENDING_REQUESTS)
		{
			lookup.result.completeExceptionally(new IOException("Wiki drop-rate request queue is full"));
			return;
		}
		pendingLookups.add(lookup);
		startPendingRequests();
	}

	private void startPendingRequests()
	{
		// Keep hover bursts polite and bounded without blocking OkHttp's worker.
		while (activeRequests < MAX_CONCURRENT_REQUESTS && !pendingLookups.isEmpty())
		{
			PendingLookup lookup = pendingLookups.remove();
			activeRequests++;
			request(lookup, lookup.npcId);
		}
	}

	private void request(PendingLookup lookup, Integer npcId)
	{
		Request request = new Request.Builder()
			.url(buildUrl(lookup.sourceName, npcId))
			.header("User-Agent", USER_AGENT)
			.build();
		Call requestCall = httpClient.newCall(request);
		activeCalls.add(requestCall);
		requestCall.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException exception)
			{
				activeCalls.remove(call);
				lookup.result.completeExceptionally(exception);
				finishRequest();
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				activeCalls.remove(call);
				try (Response closedResponse = response)
				{
					if (!enabled || lookup.generation != cacheGeneration.get())
					{
						lookup.result.completeExceptionally(
							new CancellationException("Wiki drop-rate request invalidated"));
						finishRequest();
						return;
					}
					ResponseBody body = closedResponse.body();
					if (!closedResponse.isSuccessful() || body == null)
					{
						if (npcId != null)
						{
							request(lookup, null);
							return;
						}
						lookup.result.completeExceptionally(
							new IOException("OSRS Wiki returned HTTP " + closedResponse.code()));
						finishRequest();
						return;
					}

					WikiDropTable table = WikiDropTableParser.parse(
						new ByteArrayInputStream(readBoundedBody(body)), sourceResolver);
					if (npcId != null || lookup.tableContext != null)
					{
						String selectedContext = lookup.tableContext;
						if (!table.hasContext(selectedContext))
						{
							selectedContext = contextFromFragment(closedResponse.request().url().fragment());
						}
						if (table.hasContext(selectedContext))
						{
							table = table.selectContext(selectedContext);
						}
					}
					// NPC IDs disambiguate variants when possible. Historical records may
					// lack an ID, and some Wiki pages only resolve through their name.
					if (table.isEmpty() && npcId != null)
					{
						request(lookup, null);
						return;
					}
					if (table.isEmpty())
					{
						lookup.result.completeExceptionally(
							new IOException("OSRS Wiki page has no resolvable drop table"));
						finishRequest();
						return;
					}
					lookup.result.complete(table);
					finishRequest();
				}
				catch (Exception exception)
				{
					lookup.result.completeExceptionally(exception);
					finishRequest();
				}
			}
		});
	}

	private static byte[] readBoundedBody(ResponseBody body) throws IOException
	{
		long declaredLength = body.contentLength();
		if (declaredLength > MAX_RESPONSE_BYTES)
		{
			throw new IOException("OSRS Wiki response exceeds the 4 MiB limit");
		}

		try (InputStream input = body.byteStream();
			ByteArrayOutputStream output = new ByteArrayOutputStream(
				declaredLength > 0 ? (int) declaredLength : 8192))
		{
			byte[] buffer = new byte[8192];
			int total = 0;
			int read;
			while ((read = input.read(buffer)) != -1)
			{
				total += read;
				if (total > MAX_RESPONSE_BYTES)
				{
					throw new IOException("OSRS Wiki response exceeds the 4 MiB limit");
				}
				output.write(buffer, 0, read);
			}
			return output.toByteArray();
		}
	}

	private synchronized void finishRequest()
	{
		activeRequests--;
		startPendingRequests();
	}

	static HttpUrl buildUrl(String sourceName, Integer npcId)
	{
		HttpUrl.Builder builder = HttpUrl.get(LOOKUP_URL).newBuilder()
			.addQueryParameter("type", "npc");
		if (npcId != null)
		{
			builder.addQueryParameter("id", Integer.toString(npcId));
		}
		return builder.addQueryParameter("name", sourceName).build();
	}

	private static String contextFromFragment(String fragment)
	{
		return fragment == null ? null : fragment.replace('_', ' ').trim();
	}

	private static final class LookupKey
	{
		private final String sourceName;
		private final String variant;

		private LookupKey(String sourceName, Integer npcId, String tableContext)
		{
			this.sourceName = sourceName.trim().toLowerCase(Locale.ENGLISH);
			this.variant = tableContext != null && !tableContext.trim().isEmpty()
				? "context:" + tableContext.trim().toLowerCase(Locale.ENGLISH)
				: npcId == null ? "" : "id:" + npcId;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof LookupKey))
			{
				return false;
			}
			LookupKey key = (LookupKey) other;
			return sourceName.equals(key.sourceName) && variant.equals(key.variant);
		}

		@Override
		public int hashCode()
		{
			return 31 * sourceName.hashCode() + variant.hashCode();
		}

		private String persistentKey()
		{
			return sourceName + '\0' + variant;
		}
	}

	private static final class PendingLookup
	{
		private final String sourceName;
		private final Integer npcId;
		private final String tableContext;
		private final long generation;
		private final CompletableFuture<WikiDropTable> result;

		private PendingLookup(String sourceName, Integer npcId, String tableContext, long generation,
			CompletableFuture<WikiDropTable> result)
		{
			this.sourceName = sourceName;
			this.npcId = npcId;
			this.tableContext = tableContext;
			this.generation = generation;
			this.result = result;
		}
	}

	private static final class LookupResult
	{
		private final WikiDropTable table;
		private final Throwable error;

		private LookupResult(WikiDropTable table, Throwable error)
		{
			this.table = table;
			this.error = error;
		}
	}
}

